  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C21","C23","C143","C149","C109","C127","C133","C119","C142","C154","C165","C175"],
  "contradictory_card_ids": ["C117","C163","C191"],
  "prediction_basis_card_ids": ["C21","C23","C143","C149","C109","C127","C133","C119","C142","C154","C165","C175","C117","C163","C191"],
  "claims": [
    {
      "claim": "L5 shows haloperidol is not an MDR1/P-gp substrate, with efflux ratio about 0.96 in MDR1-overexpressing cells (C165), supporting the query's haloperidol-like 4-fluorophenyl ketone piperidine motif against P-gp-mediated gut-wall efflux.",
      "card_ids": ["C165"]
    },
    {
      "claim": "L5 confirms high absorptive Caco-2 A-to-B permeability for domperidone above 1e-5 cm/s (C175), consistent with L4 domperidone and haloperidol permeability records (C143, C149, C109, C127, C133, C119, C142, C154), supporting the absorption component of the query's hybrid scaffold.",
      "card_ids": ["C175","C143","C149","C109","C127","C133","C119","C142","C154"]
    },
    {
      "claim": "L5 also contains efflux liabilities in related molecules: risperidone is a P-gp substrate (C163) and fexofenadine is a P-gp substrate in Caco-2/CPT-P1 (C191), while L4 domperidone B-to-A Papp is high (C117); these are mechanistic caveats for possible presystemic loss but are not direct F below 20 percent outcomes.",
      "card_ids": ["C163","C191","C117"]
    },
    {
      "claim": "The closest direct L1 absolute F evidence remains ketanserin at 49.3 plus or minus 18.0 percent, range 27 to 69 percent (C21), and 60 percent by F equals 1 minus E (C23), which is above the 20 percent threshold and supports high for the shared 4-fluorophenyl ketone piperidine core.",
      "card_ids": ["C21","C23"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C165","C175","C163","C191"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the exact query molecule.",
    "No query-specific P-gp or BCRP efflux data; L5 records are for analogs such as haloperidol, domperidone, risperidone, and fexofenadine.",
    "Domperidone B-to-A efflux (C117) and fexofenadine or risperidone P-gp substrate status raise uncertainty about the benzimidazolone and zwitterionic motifs, but no direct F below 20 percent evidence exists.",
    "No first-pass hepatic metabolism or systemic clearance data for the query are available."
  ],
  "decision_summary": "High is retained with moderate confidence. L5 adds haloperidol non-MDR1-substrate evidence (C165) and domperidone high A-to-B permeability (C175), supporting the query's core motifs against gut-wall efflux, while risperidone and fexofenadine P-gp substrate records (C163, C191) and domperidone B-to-A efflux (C117) are mechanistic caveats only. The closest direct L1 F evidence, ketanserin at 49 to 60 percent (C21, C23), remains above threshold, and no affirmative F below 20 percent evidence was added."
}

